const app=document.getElementById('app');
async function load(){try{let r=await fetch('/api/system');if(r.status===401){const d=await fetch('/api/auth/discover').then(x=>x.json());app.innerHTML='<section class="connect"><div class="mark">IP</div><h1>Welcome to InfraPilot</h1><p>'+ (d.available?'Device detected':'No device detected') +'</p>'+(d.available?'<p class="muted">Device: '+d.device_id+'</p><button id="login">Authenticate</button>':'<p class="muted">Run <code>infrapilot sk create</code>, then refresh.</p>')+'<p id="error" class="muted">The private key stays in the local Agent.</p></section>';if(d.available)document.getElementById('login').onclick=()=>login(d.device_id);return}const system=await r.json();show(system)}catch(e){document.getElementById('message').textContent='Unable to connect'}}
async function login(id){const error=document.getElementById('error');try{let r=await fetch('/api/auth/challenge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_id:id})});if(!r.ok)throw Error('Device not paired');let c=await r.json();let b=await fetch('http://127.0.0.1:8091/sign',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge:c.challenge})});if(!b.ok)throw Error('Local Agent unavailable');let s=await b.json();r=await fetch('/api/auth/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge_id:c.challenge_id,signature:s.signature})});if(!r.ok)throw Error('Device authentication failed');let session=await r.json();sessionStorage.setItem('infrapilot_session',session.session);const data=await fetch('/api/system',{headers:{Authorization:'Bearer '+session.session}}).then(x=>x.json());show(data)}catch(e){error.textContent=e.message}}
function show(system){app.innerHTML='<div class="dashboard"><header class="top"><div><div class="eyebrow">Infrastructure control plane</div><h1>InfraPilot</h1></div><span class="status">Connected</span></header><section class="grid"><article class="card"><h2>System</h2><div class="value">'+(system.os||'Unknown')+'</div><p class="muted">'+(system.kernel||'')+'</p></article><article class="card"><h2>Compute</h2><div class="value">'+(system.cpus||'--')+' CPUs</div></article><article class="card"><h2>Services</h2><div class="value status">Agent</div></article><article class="card"><h2>Modules</h2><div class="empty">No modules installed</div></article></section></div>'}
load();
